import crypto from 'node:crypto';
import { HttpError } from './http.js';
import { batchFileUpload, buildPayNowInvoiceFile, requestFileUploadReport, requestPayNowInvoice } from './netcash.js';
import { loadPaymentQuote, validCustomerEmail } from './loan-payments.js';
import { loadNetcashCredentials } from './provider-secrets.js';
import { dbInsert, dbSelect, dbUpdate, logCommunication } from './supabase-rest.js';

function reference() {
  return `KR${Date.now().toString(36).toUpperCase()}${crypto.randomBytes(4).toString('hex').toUpperCase()}`.slice(0,25);
}

function johannesburgEndOfDay(asOf) {
  return `${String(asOf).slice(0,10)}T23:59:59+02:00`;
}

async function settings(paymentType, source) {
  const [lenderRows, netcashRows, credentials] = await Promise.all([
    dbSelect('lender_settings',{ select:'payment_request_provider,settlement_payments_enabled,automatic_payment_requests',id:'eq.true',limit:1 }),
    dbSelect('netcash_config',{ select:'*',id:'eq.true',limit:1 }),
    loadNetcashCredentials()
  ]);
  const lender = lenderRows?.[0] || {};
  const netcash = netcashRows?.[0] || {};
  if (lender.payment_request_provider !== 'netcash') throw new HttpError(409,'Netcash is not the active payment-request provider.','provider_not_active');
  if (!netcash.enabled || netcash.validation_status !== 'validated' || !netcash.payment_requests_enabled || !credentials?.payNowServiceKey) {
    throw new HttpError(409,'Netcash Pay Now is not connected and enabled.','netcash_paynow_not_ready');
  }
  if (paymentType === 'settlement' && !lender.settlement_payments_enabled) throw new HttpError(409,'Early settlement payments are disabled.','settlements_disabled');
  if (source === 'automatic' && !lender.automatic_payment_requests) throw new HttpError(409,'Automatic payment requests are disabled.','automatic_requests_disabled');
  return { lender,netcash,credentials };
}

function tag(source,name) {
  const match = String(source || '').match(new RegExp(`<(?:\\w+:)?${name}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/(?:\\w+:)?${name}>`,'i'));
  return match ? match[1].trim().replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&amp;/g,'&') : null;
}

function loadReportState(raw) {
  const text = String(raw || '').trim();
  if (!text || /FILE NOT READY/i.test(text)) return { ready:false,status:'file_not_ready' };
  const begin = text.split(/\r?\n/).find(line => line.startsWith('###BEGIN')) || '';
  const result = String(begin.split('\t')[2] || '').trim().toUpperCase();
  if (result === 'SUCCESSFUL') return { ready:true,status:'successful' };
  if (result === 'SUCCESSFUL WITH ERRORS') return { ready:true,status:'successful_with_errors' };
  if (result === 'UNSUCCESSFUL' || /^100$|^200$/.test(text) || text.includes('###ERROR')) return { ready:true,status:'unsuccessful' };
  return { ready:false,status:'processing' };
}

async function tryInvoice(serviceKey,fileToken) {
  for (let attempt=0;attempt<3;attempt+=1) {
    if (attempt) await new Promise(resolve => setTimeout(resolve,650));
    const xml = await requestPayNowInvoice(serviceKey,fileToken);
    if (!xml || /FILE NOT READY/i.test(xml)) continue;
    return {
      clientReference:tag(xml,'ClientReference'), uniqueReference:tag(xml,'UniqueReference'), securityToken:tag(xml,'SecurityToken'), raw:xml.slice(0,12000)
    };
  }
  return null;
}

async function assertNoCollectionConflict(quote,paymentType) {
  if (paymentType === 'instalment' && quote.schedule?.id) {
    const activeDebit = await dbSelect('netcash_collection_instructions',{
      select:'id,status,action_date,due_date',schedule_id:`eq.${quote.schedule.id}`,status:'in.(queued,submitted,accepted)',limit:1
    });
    if (activeDebit?.length) {
      throw new HttpError(409,'A Netcash debit order is already queued or submitted for this instalment. Do not send a Pay Now request until that debit is cancelled, fails or is reconciled.','netcash_collection_already_active');
    }
    const pending = await dbSelect('netcash_payment_requests',{ select:'id',schedule_id:`eq.${quote.schedule.id}`,status:'in.(initializing,pending)',limit:1 });
    if (pending?.length) throw new HttpError(409,'A Netcash payment request is already active for this instalment.','payment_request_exists');
    return;
  }
  if (paymentType === 'settlement') {
    const pendingSettlement = await dbSelect('netcash_payment_requests',{ select:'id',loan_id:`eq.${quote.loan.id}`,payment_type:'eq.settlement',status:'in.(initializing,pending)',limit:1 });
    if (pendingSettlement?.length) throw new HttpError(409,'A Netcash settlement request is already active for this loan.','settlement_request_exists');
    const activeDebit = await dbSelect('netcash_collection_instructions',{
      select:'id,status,action_date,due_date',loan_id:`eq.${quote.loan.id}`,status:'in.(submitted,accepted)',limit:1
    });
    if (activeDebit?.length) {
      throw new HttpError(409,'A debit-order batch for this loan has already been submitted. Cancel or resolve that batch before sending an early-settlement request.','settlement_conflicts_with_submitted_debit');
    }
  }
}

export async function sendNetcashPaymentRequest({ loanId,scheduleId=null,paymentType='instalment',source='manual',triggerKind='manual',initiatedBy=null,userId=null }) {
  const { netcash,credentials } = await settings(paymentType,source);
  const quote = await loadPaymentQuote({ loanId,scheduleId,paymentType,userId });
  if (!quote.profile) throw new HttpError(409,'The client profile could not be found.','customer_profile_required');
  const email = validCustomerEmail(quote.profile.email);
  const mobile = String(quote.profile.mobile || '').trim();
  if (netcash.send_email && !email && netcash.send_sms && !mobile) throw new HttpError(409,'The client needs an email address or mobile number for a Netcash payment request.','customer_contact_required');
  if (netcash.send_email && !email && !netcash.send_sms) throw new HttpError(409,'The client needs a valid email address for Netcash payment requests.','customer_email_required');
  if (netcash.send_sms && !mobile && !netcash.send_email) throw new HttpError(409,'The client needs a mobile number for Netcash payment requests.','customer_mobile_required');
  await assertNoCollectionConflict(quote,paymentType);

  const ref = reference();
  const expiresAt = paymentType === 'settlement' ? johannesburgEndOfDay(quote.asOf) : null;
  let created;
  try {
    created = await dbInsert('netcash_payment_requests',{
      loan_id:quote.loan.id,schedule_id:quote.schedule?.id || null,user_id:quote.loan.user_id,
      payment_type:paymentType,source,trigger_kind:triggerKind,amount:quote.amount,due_date:quote.dueDate,
      reference:ref,status:'initializing',expires_at:expiresAt,
      provider_metadata:{ quote_as_of:quote.asOf,quote_components:quote.components,initiated_by:initiatedBy || null }
    });
  } catch (error) {
    if (paymentType === 'settlement' && (error.databaseCode === '23505' || error.code === '23505')) {
      throw new HttpError(409,'A Netcash settlement request is already active for this loan.','settlement_request_exists');
    }
    throw error;
  }
  const local = created?.[0];
  if (!local) throw new HttpError(502,'The Netcash payment request could not be saved.','database_error');

  const account = quote.loan.account_number || 'loan account';
  const description = paymentType === 'settlement' ? `Early settlement ${account}` : `Instalment ${quote.schedule.instalment_number} ${account}`;
  const batchName = `KR-PAYNOW-${ref}`.slice(0,50);
  const file = buildPayNowInvoiceFile({
    serviceKey:credentials.payNowServiceKey,softwareVendorKey:netcash.software_vendor_key,batchName,reference:ref,
    amount:quote.amount,description,email,mobile,sendSms:netcash.send_sms,sendEmail:netcash.send_email,
    extra1:local.id,extra2:quote.loan.id,extra3:quote.schedule?.id || ''
  });

  try {
    const fileToken = await batchFileUpload(credentials.payNowServiceKey,file);
    let reportRaw = '';
    try { reportRaw = await requestFileUploadReport(credentials.payNowServiceKey,fileToken); } catch {}
    const report = loadReportState(reportRaw);
    if (report.ready && report.status !== 'successful') {
      await dbUpdate('netcash_payment_requests',{ id:`eq.${local.id}` },{
        file_token:fileToken,status:'failed',failure_message:`Netcash Pay Now load report: ${report.status}.`,
        provider_metadata:{ ...local.provider_metadata,batch_name:batchName,load_status:report.status,load_report:String(reportRaw).slice(0,12000) },updated_at:new Date().toISOString()
      });
      throw new HttpError(409,'Netcash rejected the Pay Now invoice batch.','netcash_paynow_load_failed');
    }
    const invoice = await tryInvoice(credentials.payNowServiceKey,fileToken);
    const ready = Boolean(invoice?.uniqueReference || invoice?.securityToken);
    const updatedRows = await dbUpdate('netcash_payment_requests',{ id:`eq.${local.id}` },{
      file_token:fileToken,
      security_token:ready ? (invoice.securityToken || null) : null,
      provider_reference:ready ? (invoice.uniqueReference || ref) : null,
      status:ready ? 'pending' : 'initializing',
      notified_at:ready ? new Date().toISOString() : null,
      failure_message:null,
      provider_metadata:{ ...local.provider_metadata,batch_name:batchName,client_reference:invoice?.clientReference || null,invoice_ready:ready,load_status:report.status },
      updated_at:new Date().toISOString()
    });
    await logCommunication({
      userId:quote.loan.user_id,loanId:quote.loan.id,createdBy:initiatedBy,
      subject:paymentType === 'settlement' ? 'Netcash early settlement request' : 'Netcash instalment payment request',
      message:ready
        ? `Netcash Pay Now request ${ref} sent for R${quote.amount.toFixed(2)} due ${quote.dueDate}.`
        : `Netcash Pay Now request ${ref} queued for R${quote.amount.toFixed(2)} while Netcash prepares the invoice.`
    });
    return { request:updatedRows?.[0] || local,quote,invoiceReady:ready };
  } catch (error) {
    if (error?.code !== 'netcash_paynow_load_failed') {
      await dbUpdate('netcash_payment_requests',{ id:`eq.${local.id}` },{ status:'failed',failure_message:String(error.message || 'Netcash request failed').slice(0,500),updated_at:new Date().toISOString() }).catch(()=>{});
    }
    throw error;
  }
}

import crypto from 'node:crypto';
import { HttpError } from './http.js';
import { NETCASH_DEFAULT_SVK } from './netcash.js';

const PARTNER_URL = 'https://ws.netcash.co.za/NIWS/NIWS_Partner.svc';

function xml(value) {
  return String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'})[char]);
}
function unxml(value) {
  return String(value ?? '').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&apos;/g,"'").replace(/&amp;/g,'&');
}
function tag(source,name) {
  const match=String(source||'').match(new RegExp(`<(?:\\w+:)?${name}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/(?:\\w+:)?${name}>`,'i'));
  return match?unxml(match[1].trim()):null;
}
function blocks(source,name) {
  return [...String(source||'').matchAll(new RegExp(`<(?:\\w+:)?${name}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/(?:\\w+:)?${name}>`,'gi'))].map(match=>match[1]);
}

async function partnerValidate({accountNumber,softwareVendorKey,services}) {
  const action='http://tempuri.org/NIWS_Partner/ValidateServiceKey';
  const serviceXml=services.map(service=>`<d:ServiceInfo><d:ServiceId>${xml(service.id)}</d:ServiceId><d:ServiceKey>${xml(service.key)}</d:ServiceInfo>`).join('');
  const envelope=`<?xml version="1.0" encoding="utf-8"?><s:Envelope xmlns:s="http://www.w3.org/2003/05/soap-envelope" xmlns:a="http://www.w3.org/2005/08/addressing"><s:Header><a:Action s:mustUnderstand="1">${action}</a:Action><a:MessageID>urn:uuid:${crypto.randomUUID()}</a:MessageID><a:ReplyTo><a:Address>http://www.w3.org/2005/08/addressing/anonymous</a:Address></a:ReplyTo><a:To s:mustUnderstand="1">${PARTNER_URL}</a:To></s:Header><s:Body><ValidateServiceKey xmlns="http://tempuri.org/"><request xmlns:d="http://schemas.datacontract.org/2004/07/NIWS_Partner" xmlns:i="http://www.w3.org/2001/XMLSchema-instance"><d:SoftwareVendorKey>${xml(softwareVendorKey)}</d:SoftwareVendorKey><d:MerchantAccount>${xml(accountNumber)}</d:MerchantAccount><d:ServiceInfoList>${serviceXml}</d:ServiceInfoList></request></ValidateServiceKey></s:Body></s:Envelope>`;
  const response=await fetch(PARTNER_URL,{method:'POST',headers:{'Content-Type':`application/soap+xml; charset=utf-8; action="${action}"`},body:envelope,signal:AbortSignal.timeout(25000)});
  const text=await response.text();
  if(!response.ok||/<(?:\w+:)?Fault[\s>]/i.test(text)){
    throw new HttpError(response.status>=500?502:400,tag(text,'faultstring')||tag(text,'Text')||`Netcash returned HTTP ${response.status}.`,'netcash_partner_validation_failed');
  }
  const statusRows=blocks(text,'ServiceInfoResponse').map(block=>({id:tag(block,'ServiceId'),status:tag(block,'ServiceStatus')}));
  return { accountStatus:tag(text,'AccountStatus'), serviceStatuses:statusRows };
}

export async function validateNetcashProductionReadiness(credentials, config) {
  if (!config?.account_number) throw new HttpError(400,'Enter the lender Netcash account number first.','netcash_account_required');
  const services=[];
  if(credentials?.debitOrderServiceKey)services.push({id:'1',key:credentials.debitOrderServiceKey,name:'Debit orders'});
  if(credentials?.creditorServiceKey)services.push({id:'2',key:credentials.creditorServiceKey,name:'Creditor payments'});
  if(credentials?.riskServiceKey||credentials?.riskReportsServiceKey)services.push({id:'3',key:credentials.riskServiceKey||credentials.riskReportsServiceKey,name:'Risk reports'});
  if(credentials?.accountServiceKey)services.push({id:'5',key:credentials.accountServiceKey,name:'Account service'});
  if(credentials?.payNowServiceKey)services.push({id:'14',key:credentials.payNowServiceKey,name:'Pay Now'});
  if(!services.length)throw new HttpError(400,'No Netcash service keys are configured.','netcash_service_key_required');

  const result=await partnerValidate({accountNumber:config.account_number,softwareVendorKey:config.software_vendor_key||NETCASH_DEFAULT_SVK,services});
  const byId=new Map(result.serviceStatuses.map(item=>[String(item.id),item.status]));
  const checked=services.map(item=>({id:item.id,name:item.name,status:byId.get(item.id)||null,valid:byId.get(item.id)==='001'}));
  const required=[];
  if(config.standard_debit_orders_enabled||config.emandate_enabled||config.debicheck_enabled||config.registered_mandate_enabled)required.push('1');
  if(config.creditor_payments_enabled)required.push('2');
  if(config.avs_enabled||config.id_verification_enabled||config.bulk_avs_enabled)required.push('3');
  if(config.standard_debit_orders_enabled||config.emandate_enabled||config.debicheck_enabled||config.creditor_payments_enabled||config.bulk_statement_enabled)required.push('5');
  if(config.payment_requests_enabled||config.paynow_ecommerce_enabled||config.paynow_qr_enabled||config.paynow_subscriptions_enabled||config.paynow_refunds_enabled)required.push('14');

  const missingRequired=required.filter(id=>!services.some(service=>service.id===id));
  const invalidRequired=checked.filter(service=>required.includes(service.id)&&!service.valid).map(service=>service.id);
  const accountValid=result.accountStatus==='001';
  const valid=accountValid&&missingRequired.length===0&&invalidRequired.length===0;
  return {
    valid,
    accountValid,
    accountStatus:result.accountStatus,
    services:checked,
    requiredServiceIds:[...new Set(required)],
    missingRequiredServiceIds:missingRequired,
    invalidRequiredServiceIds:invalidRequired,
    checkedAt:new Date().toISOString()
  };
}

import { HttpError } from './http.js';

const NIF_URL = 'https://ws.netcash.co.za/NIWS/NIWS_NIF.svc';

function xml(value) {
  return String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[char]));
}
function unxml(value) {
  return String(value ?? '').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&apos;/g,"'").replace(/&amp;/g,'&');
}
function tag(source, name) {
  const match = String(source || '').match(new RegExp(`<(?:\\w+:)?${name}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/(?:\\w+:)?${name}>`, 'i'));
  return match ? unxml(match[1].trim()) : null;
}
async function nifCall(method, params, timeout = 30000) {
  const action = `http://tempuri.org/NIWS_NIF/${method}`;
  const payload = Object.entries(params).map(([key,value]) => `<${key}>${xml(value)}</${key}>`).join('');
  const envelope = `<?xml version="1.0" encoding="utf-8"?><soap:Envelope xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:xsd="http://www.w3.org/2001/XMLSchema" xmlns:soap="http://schemas.xmlsoap.org/soap/envelope/"><soap:Body><${method} xmlns="http://tempuri.org/">${payload}</${method}></soap:Body></soap:Envelope>`;
  const response = await fetch(NIF_URL, { method:'POST', headers:{'Content-Type':'text/xml; charset=utf-8',SOAPAction:`"${action}"`}, body:envelope, signal:AbortSignal.timeout(timeout) });
  const text = await response.text();
  if (!response.ok || /<(?:\w+:)?Fault[\s>]/i.test(text)) {
    const reason = tag(text,'faultstring') || tag(text,'Text') || `Netcash ${method} failed.`;
    throw new HttpError(response.status >= 500 ? 502 : 400, reason, 'netcash_error');
  }
  return String(tag(text, `${method}Result`) || '').trim();
}

export async function requestMandateData(serviceKey) {
  const result = await nifCall('RequestMandateData', { ServiceKey: serviceKey });
  if (result === '100') throw new HttpError(401, 'Netcash rejected the Debit Order service key.', 'netcash_auth_failed');
  if (result === '200' || !result) throw new HttpError(502, 'Netcash could not create the mandate status file.', 'netcash_mandate_status_error');
  return result;
}

export async function retrieveMandateData(serviceKey, fileToken) {
  return nifCall('RetrieveMandateData', { ServiceKey: serviceKey, FileToken: fileToken });
}

export function parseMandateData(file) {
  const result = [];
  for (const line of String(file || '').split(/\r?\n/)) {
    if (!line || line.startsWith('###')) continue;
    const fields = line.split('\t');
    if (!/^\d+$/.test(String(fields[0] || '').trim()) || !fields[1]) continue;
    result.push({
      statusCode: String(fields[0]).trim(),
      accountReference: String(fields[1]).trim(),
      mandateName: fields[2] || null,
      amount: Number(fields[3] || 0),
      active: String(fields[18] || '') === '1',
      raw: fields
    });
  }
  return result;
}

export function mandateState(statusCode, active = false) {
  const code = String(statusCode || '');
  if (code === '6' || code === '9') return { mandateStatus:'accepted', providerStatus: active || code === '9' ? 'active' : 'pending' };
  if (code === '2') return { mandateStatus:'awaiting_authorisation', providerStatus:'pending' };
  if (['3','4','5','10'].includes(code)) return { mandateStatus: code === '5' ? 'rejected' : 'failed', providerStatus:'failed' };
  return { mandateStatus:'requested', providerStatus:'pending' };
}

export async function requestPresentationDate(serviceKey, actionDate, instruction = 'CompactTwoDay') {
  const cleanDate = String(actionDate || '').replace(/-/g,'');
  const result = await nifCall('RequestPresentationDate', {
    ServiceKey: serviceKey, Date: cleanDate, Instruction: instruction, ForwardActionDate: '0'
  });
  if (result === '100') throw new HttpError(401, 'Netcash rejected the Debit Order service key.', 'netcash_auth_failed');
  if (result === '200' || !/^\d{8}$/.test(result)) return null;
  return `${result.slice(0,4)}-${result.slice(4,6)}-${result.slice(6,8)}`;
}

export async function requestActionDate(serviceKey, actionDate, instruction = 'CompactTwoDay', forward = true) {
  const cleanDate = String(actionDate || '').replace(/-/g,'');
  const result = await nifCall('RequestActionDate', {
    ServiceKey: serviceKey, Date: cleanDate, Instruction: instruction, ForwardActionDate: forward ? '1' : '0'
  });
  if (result === '100') throw new HttpError(401, 'Netcash rejected the Debit Order service key.', 'netcash_auth_failed');
  if (result === '200' || !/^\d{8}$/.test(result)) return null;
  return `${result.slice(0,4)}-${result.slice(4,6)}-${result.slice(6,8)}`;
}

export async function checkPayNowTransaction(requestTrace) {
  const trace = String(requestTrace || '').trim();
  if (!/^[A-Za-z0-9._-]{3,120}$/.test(trace)) throw new HttpError(400, 'Netcash transaction trace is invalid.', 'invalid_netcash_trace');
  const response = await fetch(`https://ws.netcash.co.za/PayNow/TransactionStatus/Check?RequestTrace=${encodeURIComponent(trace)}`, { signal:AbortSignal.timeout(15000) });
  if (!response.ok) throw new HttpError(502, 'Netcash transaction verification failed.', 'netcash_verification_failed');
  const data = await response.json().catch(() => null);
  if (!data || String(data.RequestTrace || '') !== trace) throw new HttpError(502, 'Netcash returned an invalid transaction status.', 'netcash_verification_failed');
  return data;
}

import crypto from 'node:crypto';
import { HttpError } from './http.js';

export const NETCASH_DEFAULT_SVK = '24ade73c-98cf-47b3-99be-cc7b867b3080';
const NIF_URL = 'https://ws.netcash.co.za/NIWS/NIWS_NIF.svc';
const PARTNER_URL = 'https://ws.netcash.co.za/NIWS/NIWS_Partner.svc';

function xml(value) {
  return String(value ?? '').replace(/[&<>"']/g, char => ({
    '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'
  })[char]);
}
function unxml(value) {
  return String(value ?? '').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&apos;/g,"'").replace(/&amp;/g,'&');
}
function tag(source,name) {
  const match=String(source||'').match(new RegExp(`<(?:\\w+:)?${name}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/(?:\\w+:)?${name}>`,'i'));
  return match?unxml(match[1].trim()):null;
}
function allBlocks(source,name) {
  return [...String(source||'').matchAll(new RegExp(`<(?:\\w+:)?${name}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/(?:\\w+:)?${name}>`,'gi'))].map(match=>match[1]);
}
function soapFault(text,status) {
  const reason=tag(text,'faultstring')||tag(text,'Text')||tag(text,'Reason')||`Netcash web service returned HTTP ${status}.`;
  return new HttpError(status>=500?502:400,reason,'netcash_error');
}
async function postNif(method,methodBody,timeout=30000) {
  const action=`http://tempuri.org/NIWS_NIF/${method}`;
  const envelope=`<?xml version="1.0" encoding="utf-8"?><soap:Envelope xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:xsd="http://www.w3.org/2001/XMLSchema" xmlns:soap="http://schemas.xmlsoap.org/soap/envelope/"><soap:Body><${method} xmlns="http://tempuri.org/">${methodBody}</${method}></soap:Body></soap:Envelope>`;
  const response=await fetch(NIF_URL,{method:'POST',headers:{'Content-Type':'text/xml; charset=utf-8',SOAPAction:`"${action}"`},body:envelope,signal:AbortSignal.timeout(timeout)});
  const text=await response.text();
  if(!response.ok||/<(?:\w+:)?Fault[\s>]/i.test(text))throw soapFault(text,response.status);
  return{text,result:tag(text,`${method}Result`)};
}
async function nifCall(method,params,timeout=30000) {
  const body=Object.entries(params).map(([key,value])=>`<${key}>${xml(value)}</${key}>`).join('');
  return postNif(method,body,timeout);
}
async function nifMethodParametersCall(method,params,timeout=30000) {
  const fields=Object.entries(params).map(([key,value])=>`<${key}>${xml(value)}</${key}>`).join('');
  return postNif(method,`<MethodParameters>${fields}</MethodParameters>`,timeout);
}

async function partnerValidate({accountNumber,softwareVendorKey,services}) {
  const action='http://tempuri.org/NIWS_Partner/ValidateServiceKey';
  const serviceXml=services.map(service=>`<d:ServiceInfo><d:ServiceId>${xml(service.id)}</d:ServiceId><d:ServiceKey>${xml(service.key)}</d:ServiceInfo>`).join('');
  const messageId=`urn:uuid:${crypto.randomUUID()}`;
  const envelope=`<?xml version="1.0" encoding="utf-8"?><s:Envelope xmlns:s="http://www.w3.org/2003/05/soap-envelope" xmlns:a="http://www.w3.org/2005/08/addressing"><s:Header><a:Action s:mustUnderstand="1">${action}</a:Action><a:MessageID>${messageId}</a:MessageID><a:ReplyTo><a:Address>http://www.w3.org/2005/08/addressing/anonymous</a:Address></a:ReplyTo><a:To s:mustUnderstand="1">${PARTNER_URL}</a:To></s:Header><s:Body><ValidateServiceKey xmlns="http://tempuri.org/"><request xmlns:d="http://schemas.datacontract.org/2004/07/NIWS_Partner" xmlns:i="http://www.w3.org/2001/XMLSchema-instance"><d:SoftwareVendorKey>${xml(softwareVendorKey)}</d:SoftwareVendorKey><d:MerchantAccount>${xml(accountNumber)}</d:MerchantAccount><d:ServiceInfoList>${serviceXml}</d:ServiceInfoList></request></ValidateServiceKey></s:Body></s:Envelope>`;
  const response=await fetch(PARTNER_URL,{method:'POST',headers:{'Content-Type':`application/soap+xml; charset=utf-8; action="${action}"`},body:envelope,signal:AbortSignal.timeout(20000)});
  const text=await response.text();
  if(!response.ok||/<(?:\w+:)?Fault[\s>]/i.test(text))throw soapFault(text,response.status);
  const accountStatus=tag(text,'AccountStatus');
  const blocks=allBlocks(text,'ServiceInfoResponse');
  const serviceStatuses=blocks.map(block=>({id:tag(block,'ServiceId'),status:tag(block,'ServiceStatus')}));
  if(!serviceStatuses.length){
    const ids=[...text.matchAll(/<(?:\w+:)?ServiceId>(.*?)<\/(?:\w+:)?ServiceId>/gi)].map(match=>unxml(match[1]));
    const statuses=[...text.matchAll(/<(?:\w+:)?ServiceStatus>(.*?)<\/(?:\w+:)?ServiceStatus>/gi)].map(match=>unxml(match[1]));
    ids.forEach((id,index)=>serviceStatuses.push({id,status:statuses[index]||null}));
  }
  return{accountStatus,serviceStatuses,raw:text};
}

export async function validateNetcashCredentials(credentials,config) {
  const services=[];
  if(credentials.debitOrderServiceKey)services.push({id:'1',key:credentials.debitOrderServiceKey,name:'Debit orders'});
  if(credentials.riskReportsServiceKey)services.push({id:'3',key:credentials.riskReportsServiceKey,name:'Risk reports'});
  if(credentials.accountServiceKey)services.push({id:'5',key:credentials.accountServiceKey,name:'Account service'});
  if(credentials.payNowServiceKey)services.push({id:'14',key:credentials.payNowServiceKey,name:'Pay Now'});
  if(!services.length)throw new HttpError(400,'Enter at least one Netcash service key.','netcash_service_key_required');
  const result=await partnerValidate({accountNumber:config.account_number,softwareVendorKey:config.software_vendor_key||NETCASH_DEFAULT_SVK,services});
  const statusById=new Map(result.serviceStatuses.map(item=>[String(item.id),item.status]));
  const checked=services.map(item=>({...item,status:statusById.get(item.id)||null,valid:statusById.get(item.id)==='001'}));
  return{accountStatus:result.accountStatus,accountValid:result.accountStatus==='001',services:checked,valid:result.accountStatus==='001'&&checked.every(item=>item.valid)};
}

